package com.opensocket.aievent.core.iam.authentication.domain;
import java.time.Instant;import java.util.Objects;import java.util.Set;
public record ReauthenticationGrant(String grantId,String sessionId,String subjectId,Set<String> purposes,Instant issuedAt,Instant expiresAt,boolean consumed,long version){public ReauthenticationGrant{grantId=Text.required(grantId,"grantId",128);sessionId=Text.required(sessionId,"sessionId",256);subjectId=Text.required(subjectId,"subjectId",128);purposes=purposes==null?Set.of():Set.copyOf(purposes);if(purposes.isEmpty())throw new IllegalArgumentException("purposes are required");Objects.requireNonNull(issuedAt,"issuedAt");Objects.requireNonNull(expiresAt,"expiresAt");if(!expiresAt.isAfter(issuedAt))throw new IllegalArgumentException("expiresAt must be after issuedAt");if(version<1)throw new IllegalArgumentException("version must be positive");}public boolean validFor(String purpose,Instant at){return !consumed&&at.isBefore(expiresAt)&&purposes.contains(purpose);}public ReauthenticationGrant consume(){if(consumed)throw new AuthenticationDomainException(AuthenticationReasonCode.AUTH_REAUTHENTICATION_EXPIRED,"Reauthentication grant already consumed");return new ReauthenticationGrant(grantId,sessionId,subjectId,purposes,issuedAt,expiresAt,true,version+1);}}
